    html: "<!doctype html>\n<!--\n  The Applet canvas page.\n\n  `AppletCanvas.vue` owns the frame — the header, the two states, the slide —\n  and mounts this page in `frockbot.right-panel` for the \"ready\" half. All this\n  page does is nest the Applet's own UI artifact and hand it the one thing it\n  cannot fetch for itself: the short-lived viewer token, the socket URL, and\n  the theme tokens, in the `init` message `listenForAppletInit` in\n  `@frockbot/applet-sdk/client` waits for.\n\n  Two frames rather than one because the trust boundaries differ. This page is\n  a page of the Applets Package, pinned by the Composition. The Applet inside\n  it is one User's own code, on its own generation, replaced whenever they\n  publish — so it gets its own document, and a new generation is a new frame,\n  never a reused one.\n-->\n<html lang=\"en\">\n  <head>\n    <meta charset=\"utf-8\" />\n    <title>Applet</title>\n    <style>\n      html,\n      body {\n        height: 100%;\n        margin: 0;\n        color: var(--frockbot-text);\n        background: var(--frockbot-surface);\n        font-family:\n          ui-sans-serif,\n          system-ui,\n          -apple-system,\n          sans-serif;\n        font-size: 14px;\n      }\n\n      #frame {\n        display: block;\n        width: 100%;\n        height: 100%;\n        border: 0;\n        background: var(--frockbot-surface);\n      }\n\n      #idle {\n        display: flex;\n        height: 100%;\n        align-items: center;\n        justify-content: center;\n        padding: 24px;\n        color: var(--frockbot-text-muted);\n        text-align: center;\n      }\n\n      [hidden] {\n        display: none !important;\n      }\n    </style>\n  </head>\n  <body>\n    <p id=\"idle\">This Applet has no published version yet.</p>\n    <iframe\n      id=\"frame\"\n      hidden\n      title=\"Applet\"\n      sandbox=\"allow-scripts\"\n      referrerpolicy=\"no-referrer\"\n    ></iframe>\n    <script>\n(()=>{const V=2,L=new Map(),obj=v=>v&&typeof v==='object'&&!Array.isArray(v),exact=(v,ks)=>obj(v)&&Object.keys(v).length===ks.length&&ks.every(k=>Object.prototype.hasOwnProperty.call(v,k)),str=(v,n)=>typeof v==='string'&&v.length>0&&v.length<=n,json=(v,d=0)=>d<=16&&(v===null||typeof v==='string'||typeof v==='boolean'||typeof v==='number'&&Number.isFinite(v)||Array.isArray(v)&&v.length<=256&&v.every(x=>json(x,d+1))||obj(v)&&Object.keys(v).length<=256&&Object.values(v).every(x=>json(x,d+1))),wire=v=>{try{return new TextEncoder().encode(JSON.stringify(v)).byteLength<=65536}catch{return false}};let ok,fail;const ready=new Promise((r,j)=>{ok=r;fail=j});addEventListener('message',e=>{if(e.source!==parent)return;const m=e.data;if(m?.schemaVersion!==1&&m?.schemaVersion!==2||!wire(m))return;if(m.type==='init'&&(exact(m,['schemaVersion','type','themeTokens','packageId','botId','slot'])||exact(m,['schemaVersion','type','themeTokens','packageId','botId','slot','pageId'])&&str(m.pageId,32))&&obj(m.themeTokens)&&Object.keys(m.themeTokens).length<=64&&Object.values(m.themeTokens).every(v=>typeof v==='string')&&str(m.packageId,64)&&str(m.botId,256)&&str(m.slot,160)){for(const [k,v] of Object.entries(m.themeTokens))document.documentElement.style.setProperty('--frockbot-'+k,v);ok({themeTokens:m.themeTokens,packageId:m.packageId,botId:m.botId,slot:m.slot,...(m.pageId===undefined?{}:{pageId:m.pageId})});return}if(m.type==='state'&&exact(m,['schemaVersion','type','name','value'])&&str(m.name,256)&&json(m.value))for(const fn of L.get(m.name)||[])fn(m.value)});window.frockbot={ready,callTool(name,input){parent.postMessage({schemaVersion:V,type:'callTool',name,input},'*')},subscribe(name,fn){const s=L.get(name)||new Set();s.add(fn);L.set(name,s);return()=>s.delete(fn)},resize(height=document.documentElement.scrollHeight){parent.postMessage({schemaVersion:V,type:'resize',height},'*')},focus(appletId){parent.postMessage({schemaVersion:2,type:'focus',appletId:appletId===undefined?null:appletId},'*')},openExternal(url){parent.postMessage({schemaVersion:2,type:'openExternal',url},'*')}};parent.postMessage({schemaVersion:2,type:'hello',bridgeVersion:V},'*');setTimeout(()=>fail(new Error('FrockBot iframe init timed out')),10000)})();\n    </script>\n    <script>\n      (() => {\n        const frame = document.getElementById(\"frame\");\n        const idle = document.getElementById(\"idle\");\n        let themeTokens = {};\n        let mounted = null;\n        let pending = null;\n\n        /* The Applet is told who it is once its own document has loaded. */\n        frame.addEventListener(\"load\", () => {\n          if (!pending || !frame.contentWindow) return;\n          frame.contentWindow.postMessage(\n            {\n              schemaVersion: 1,\n              type: \"init\",\n              themeTokens,\n              applet: {\n                socketUrl: pending.socketUrl,\n                token: pending.token,\n                generationId: pending.generationId,\n              },\n            },\n            \"*\",\n          );\n        });\n\n        function show(viewer) {\n          if (!viewer) {\n            mounted = null;\n            pending = null;\n            frame.hidden = true;\n            frame.removeAttribute(\"src\");\n            idle.hidden = false;\n            return;\n          }\n          idle.hidden = true;\n          frame.hidden = false;\n          pending = viewer;\n          // A new generation, a new token, or a new URL is a new document: the\n          // Applet's `init` is delivered on load and never re-sent into a page\n          // that has already connected with a token that is about to expire.\n          const identity = `${viewer.generationId}|${viewer.uiUrl}|${viewer.token}`;\n          if (identity === mounted) return;\n          mounted = identity;\n          frame.setAttribute(\"src\", viewer.uiUrl);\n        }\n\n        window.frockbot.ready.then((init) => {\n          themeTokens = init.themeTokens;\n          window.frockbot.subscribe(\"applets\", (state) => {\n            show(state && state.viewer ? state.viewer : null);\n          });\n        });\n      })();\n    </script>\n  </body>\n</html>\n",
